PROGRAM ST_H03_AGV_LASTNING
VAR
    steg      : INT := 0;
    trigDone  : R_TRIG;
    tmrRst    : TON;
END_VAR

trigDone(CLK := ST330_RB_DONE);
tmrRst(IN := (steg = 4), PT := T#500ms);

IF NOT EMG_OK THEN
    ST330_RB_START := FALSE;
    ST330_HS_REQ   := FALSE;
    ST330_HS_DONE  := FALSE;
    ST330_HS_RST   := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST330_HS_DONE := FALSE;
            ST330_HS_RST  := FALSE;
            ST330_RB_START := FALSE;
            ST330_LOD_CNT := 0;
            IF ST330_DCK_OK THEN
                ST330_HS_REQ := TRUE;
                IF ST330_HS_ACK THEN
                    steg := 1;
                END_IF;
            ELSE
                ST330_HS_REQ := FALSE;
            END_IF;
        1:
            IF NOT ST330_DCK_OK THEN
                ST330_RB_START := FALSE;
                steg := 9;
            ELSIF NOT ST330_RB_DONE AND ST330_PRT_PRS AND ST330_LOD_CNT < 4 THEN
                ST330_RB_START := TRUE;
                steg := 2;
            END_IF;
        2:
            IF NOT ST330_DCK_OK THEN
                ST330_RB_START := FALSE;
                steg := 9;
            ELSIF trigDone.Q THEN
                ST330_RB_START := FALSE;
                ST330_LOD_CNT := ST330_LOD_CNT + 1;
                IF ST330_LOD_CNT >= 4 THEN
                    ST330_HS_DONE := TRUE;
                    steg := 3;
                ELSE
                    steg := 1;
                END_IF;
            END_IF;
        3:
            IF NOT ST330_DCK_OK THEN
                ST330_HS_DONE := FALSE;
                ST330_HS_REQ  := FALSE;
                ST330_HS_RST  := TRUE;
                steg := 4;
            END_IF;
        4:
            ST330_HS_RST := TRUE;
            IF tmrRst.Q THEN
                ST330_HS_RST := FALSE;
                steg := 0;
            END_IF;
        9:
            ST330_RB_START := FALSE;
            ST330_HS_DONE := FALSE;
            IF ST330_DCK_OK THEN
                steg := 1;
            END_IF;
    END_CASE;
END_IF;
END_PROGRAM

